      lead: { name: 'THE BOOKMAKER', spr: 'grunt_m', lines: ["THE BOOKMAKER: You're the one {RIVAL} bet against? The odds are terrible. I've put my money on you.", "THE BOOKMAKER: Get round every town, and get a move on. {RIVAL}'s telling everyone you'll fail."] },
