      lead: { name: 'THE CENSUS-TAKER', spr: 'bookworm', lines: ["THE CENSUS-TAKER: You're my new assistant? Excellent. I've counted myself four times. I keep getting different answers.", "THE CENSUS-TAKER: Every household in every town. Count carefully. People move about. Creatures move about more."] },
